       r.power_factor_total_max,
       r.frequency_avg,
       r.frequency_min,
       r.frequency_max,
       r.thd_voltage_a_avg,
       r.thd_voltage_a_min,
       r.thd_voltage_a_max,
       r.thd_voltage_b_avg,
       r.thd_voltage_b_min,
       r.thd_voltage_b_max,
       r.thd_voltage_c_avg,
       r.thd_voltage_c_min,
       r.thd_voltage_c_max,
       r.thd_current_a_avg,
       r.thd_current_a_min,
       r.thd_current_a_max,
       r.thd_current_b_avg,
